generator_cmd:
python3 -I -c 'import sys;sys.path.insert(0,"tools/pyciphers");from secretpy import MyszkowskiTransposition as M;s=sys.argv[1]
for k in sys.argv[2:]:s=M().encrypt(s,k)
print(s,end="")' "$plain" tomato  # pycipher 0.5.2 ColTrans / secretpy 0.12.0 MyszkowskiTransposition .encipher/.encrypt applied once per key (punctuation kept)

oracle_cmd:
python3 -I -c 'import sys;sys.path.insert(0,"tools/pyciphers");from secretpy import MyszkowskiTransposition as M;s=sys.argv[1]
for k in reversed(sys.argv[2:]):s=M().decrypt(s,k)
print(s,end="")' "$encoded" tomato  # secretpy 0.12.0 ColumnarTransposition / MyszkowskiTransposition .decrypt, keys undone last-first
